public class BankAccount {
    private String accountNumber;
    private String owner;
    private double balance;

    public BankAccount(String accountNumber, String owner, double balance) {
        this.accountNumber = accountNumber;
        this.owner = owner;
        this.balance = balance;
    }

    // accessors
    public String getAccountNumber() { return accountNumber; }
    public String getOwner()         { return owner; }
    public double getBalance()       { return balance; }

    // behaviors, the only ways the balance can change
    public void deposit(double amount) {
        if (amount <= 0) {
            System.out.println("Deposit must be positive.");
            return;
        }
        balance += amount;
        logTransaction("Deposit", amount);
    }

    public void withdraw(double amount) {
        if (amount <= 0) {
            System.out.println("Withdrawal must be positive.");
            return;
        }
        if (amount > balance) {
            System.out.println("Insufficient funds.");
            return;
        }
        balance -= amount;
        logTransaction("Withdrawal", amount);
    }

    // helper, internal, so it is private
    private void logTransaction(String type, double amount) {
        System.out.printf("%s of %.2f, new balance %.2f%n", type, amount, balance);
    }
}

public class BankDemo {
    public static void main(String[] args) {
        BankAccount account = new BankAccount("0012345", "Ana Reyes", 5000.00);

        account.deposit(1500);
        account.withdraw(2000);
        account.withdraw(99999);
        account.deposit(-50);

        System.out.printf("Final balance: %.2f%n", account.getBalance());

        // account.balance = 1000000;   // error: balance has private access
    }
}
